from django.utils import timezone


def _due(status):
    from thiet_ke_sp.services.sla import due_at_for
    return due_at_for(status)


def _close_open_tasks(Task, dossier_id, step, actor_id, now):
    base = Task.objects.filter(
        dossier_id=dossier_id, step=step, state='open',
        receipt__isnull=True, condition__isnull=True, evaluation__isnull=True,
    )
    base.filter(is_main=True).update(state='done', completed_at=now, completed_by_id=actor_id)
    base.filter(is_main=False).update(state='cancelled', completed_at=now)


def move_sampling_into_technical(apps, schema_editor):
    # Chưa có cột co_designer (0024). Không dùng model hiện tại.
    ProductDevelopment = apps.get_model('thiet_ke_sp', 'ProductDevelopment')
    Task = apps.get_model('thiet_ke_sp', 'Task')
    AuditLog = apps.get_model('thiet_ke_sp', 'AuditLog')

    ProductDevelopment.objects.filter(status='paused', paused_from_status='sampling').update(
        paused_from_status='technical',
    )
    ProductDevelopment.objects.filter(status='paused', paused_from_status='sample_revise').update(
        paused_from_status='technical_revise',
    )
    moves = (
        ('sampling', 'technical', 'Cập nhật rập, thông số kỹ thuật & BOM'),
        ('sample_revise', 'technical_revise', 'Chỉnh rập, thông số kỹ thuật & BOM'),
    )
    for old, new, title in moves:
        for dossier in ProductDevelopment.objects.filter(status=old):
            actor_id = dossier.technician_id or dossier.owner_id or dossier.proposer_id
            now = timezone.now()
            _close_open_tasks(Task, dossier.pk, old, actor_id, now)
            dossier.status = new
            dossier.status_changed_at = now
            dossier.save(update_fields=['status', 'status_changed_at'])
            AuditLog.objects.create(
                dossier_id=dossier.pk, actor_id=actor_id, action='step_inserted',
                summary='Thêm bước Kỹ thuật trước làm mẫu.',
                from_status=old, to_status=new,
            )
            Task.objects.create(
                dossier_id=dossier.pk, step=new, role='technician', title=title, is_main=True,
                assignee_id=dossier.technician_id or dossier.owner_id, due_at=_due(new), state='open',
            )


def noop(apps, schema_editor):
    return None


